import { test, expect } from '@playwright/test';

test.describe('Long-running task persistence', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000'); // Replace with the actual URL
  });

  test('should start a long-running task and persist across refresh', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Task' }).click();
    await expect(page.getByText('Task is running...')).toBeVisible();

    await page.reload();

    await expect(page.getByText('Task is running...')).toBeVisible();
  });

  test('should show task completion after refresh', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Task' }).click();
    await expect(page.getByText('Task is running...')).toBeVisible();

    // Simulate waiting for the task to complete
    await page.waitForTimeout(5000); // Adjust timeout as necessary
    await expect(page.getByText('Task completed!')).toBeVisible();

    await page.reload();

    await expect(page.getByText('Task completed!')).toBeVisible();
  });
});
